15	/// Every other network test (`api_client_test.dart`, `header_interceptor_test.dart`,
16	/// `retry_interceptor_test.dart`) mocks `Dio` itself or drives one interceptor
17	/// in isolation — neither proves the pieces work *wired together* the way
18	/// `setupCoreDependencies` actually wires them (AD-5), nor that a retry
19	/// genuinely goes back out over the wire.
20	///
21	/// Like `bootstrap_integration_test.dart` fakes the native secure-storage
22	/// channel (no device/CI exists yet to do otherwise), this fakes only the
23	/// transport boundary (`HttpClientAdapter`) — everything above it (URL
24	/// building, both real interceptors, `ApiClient`'s mapping) is the genuine
25	/// production wiring.
26	class _FakeHttpClientAdapter implements HttpClientAdapter {
27	  final List<RequestOptions> requests = [];
28	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
29	
30	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
31	    _queue.add((statusCode: statusCode, body: body));
32	  }
33	
34	  @override
35	  Future<ResponseBody> fetch(
36	    RequestOptions options,
37	    Stream<Uint8List>? requestStream,
38	    Future<void>? cancelFuture,
39	  ) async {
40	    requests.add(options);
41	    if (_queue.isEmpty) {
42	      throw StateError(
43	        'No queued response for ${options.method} ${options.path}',
44	      );
45	    }
46	    final next = _queue.removeAt(0);
47	    return ResponseBody.fromString(
48	      jsonEncode(next.body),
49	      next.statusCode,
50	      headers: {
51	        Headers.contentTypeHeader: [Headers.jsonContentType],
52	      },
53	    );
54	  }
55	
56	  @override
57	  void close({bool force = false}) {}
58	}
59	
60	/// A minimal, real (non-mocked) in-memory implementation — this suite is
61	/// about proving the wiring, not re-verifying token-storage behavior
62	/// (already covered by `access_token_provider_test.dart`).
63	class _InMemoryAccessTokenProvider implements AccessTokenProvider {
64	  String? _token;
65	  String? _refreshToken;
66	
67	  @override
68	  Future<String?> readAccessToken() async => _token;
69	
70	  @override
71	  Future<void> saveAccessToken(String token) async => _token = token;
72	
73	  @override
74	  Future<void> clearAccessToken() async => _token = null;
75	
76	  @override
77	  Future<String?> readRefreshToken() async => _refreshToken;
78	
79	  @override
80	  Future<void> saveSession({
81	    required String accessToken,
82	    required String refreshToken,
83	  }) async {
84	    _token = accessToken;
85	    _refreshToken = refreshToken;
86	  }
87	
88	  @override
89	  Future<void> clearSession() async {
90	    _token = null;
91	    _refreshToken = null;
92	  }
93	}
94	
95	void main() {
96	  const baseUrl = 'https://host.example.com';
97	  const anonKey = 'anon-key-value';
98	
99	  late _FakeHttpClientAdapter adapter;
100	  late _InMemoryAccessTokenProvider tokenProvider;
101	  late SessionExpiryNotifierImpl sessionExpiryNotifier;
102	  late ApiClient apiClient;
103	
104	  setUp(() {
105	    adapter = _FakeHttpClientAdapter();
106	    tokenProvider = _InMemoryAccessTokenProvider();
107	    sessionExpiryNotifier = SessionExpiryNotifierImpl();
108	
109	    // Mirrors `setupCoreDependencies`'s wiring exactly: real Dio, both real
110	    // interceptors attached in the same order, header interceptor fed the
111	    // same anon key + token provider contract.
112	    final dio = Dio(BaseOptions())..httpClientAdapter = adapter;
113	    dio.interceptors.add(
114	      HeaderInterceptor(anonKey: anonKey, accessTokenProvider: tokenProvider),
115	    );
116	    dio.interceptors.add(RetryInterceptor(dio));
117	
118	    apiClient = ApiClient(
119	      dio: dio,
120	      urlBuilder: const UrlBuilder(baseUrl),
121	      sessionExpiryNotifier: sessionExpiryNotifier,
122	    );
123	  });
124	
125	  group('network pipeline — real Dio + real interceptors, faked transport', () {
126	    test('an anon-only operation (auth-login) goes out at the x-cerne-function '
