/// Only the transport boundary is faked (`HttpClientAdapter`), same as
/// `network_pipeline_integration_test.dart` — everything above it (URL
/// building, both real interceptors, `ApiClient`'s mapping) and below it
/// (real `hive_ce`, real `TextEntryCubit`/`InsertionModal` resolved from
/// the real `sl` container) is the genuine production wiring.
class _FakeHttpClientAdapter implements HttpClientAdapter {
  final List<RequestOptions> requests = [];
  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];

  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
    _queue.add((statusCode: statusCode, body: body));
  }

  @override
  Future<ResponseBody> fetch(
    RequestOptions options,
    Stream<Uint8List>? requestStream,
    Future<void>? cancelFuture,
  ) async {
    requests.add(options);
    if (_queue.isEmpty) {
      throw StateError(
        'No queued response for ${options.method} ${options.path}',
      );
    }
    final next = _queue.removeAt(0);
    return ResponseBody.fromString(
      jsonEncode(next.body),
      next.statusCode,
      headers: {
        Headers.contentTypeHeader: [Headers.jsonContentType],
      },
    );
  }

  @override
  void close({bool force = false}) {}
}

/// Full-stack E2E coverage for spec-3-1's happy path and primary failure
/// path: real `HomeChatPlaceholderScreen` "+" tap -> real `sl<TextEntryCubit>()`
/// -> real `InsertionModal` -> real `EntriesRepositoryImpl` ->
/// `EntriesRemoteDataSource`/`ApiClient`/`Dio`/both interceptors -> real
/// `entries` Hive box. Every existing test for this story mocks or fakes
/// exactly one layer in isolation (a fake `EntriesRepository` in
/// `insertion_modal_test.dart`, a mocked `EntriesRemoteDataSource` in
/// `entries_repository_impl_integration_test.dart`, no UI at all in
/// `bootstrap_integration_test.dart`'s wiring checks) — none of them drives
/// the real UI through the real DI container end to end. No
/// device/simulator/CI exists yet (AGENTS.md), so native plugins are faked
/// the same way the rest of this suite already does.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  const secureStorageChannel = MethodChannel(
    'plugins.it_nomads.com/flutter_secure_storage',
  );
  final fakeNativeStorage = <String, String>{};

  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
    final args = call.arguments as Map<dynamic, dynamic>;
    switch (call.method) {
      case 'write':
        fakeNativeStorage[args['key'] as String] = args['value'] as String;
        return null;
      case 'read':
        return fakeNativeStorage[args['key'] as String];
      case 'delete':
        fakeNativeStorage.remove(args['key'] as String);
        return null;
      case 'containsKey':
        return fakeNativeStorage.containsKey(args['key'] as String);
      default:
        return null;
    }
  }

  late FakePathProviderPlatform fakePathProvider;
  late _FakeHttpClientAdapter adapter;

  setUp(() async {
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(secureStorageChannel, handleSecureStorageCall);
    fakePathProvider = FakePathProviderPlatform();
    PathProviderPlatform.instance = fakePathProvider;

    await resetCoreDependencies();
    await setupCoreDependencies();

    // Swap only the transport boundary on the real, DI-resolved Dio
    // instance — both real interceptors (header + retry) stay attached.
    adapter = _FakeHttpClientAdapter();
    sl<Dio>().httpClientAdapter = adapter;

    // `entries-create` is a bearer-required operation (not in
    // HeaderInterceptor.anonKeyOnlyFunctions) — seed a user access token
    // through the real AccessTokenProvider (backed by the faked secure
    // storage channel above) so the real header interceptor has one to
    // send.
    await sl<AccessTokenProvider>().saveAccessToken('e2e-test-access-token');
  });

  tearDown(() async {
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
        .setMockMethodCallHandler(secureStorageChannel, null);
    fakeNativeStorage.clear();
    await Hive.close();
    await resetCoreDependencies();
    await fakePathProvider.cleanUp();
  });

  testWidgets(
    'happy path: tapping "+", typing text and tapping Salvar drives the '
    'real pipeline end to end — a genuine POST to entries-create with the '
    'right headers/body, the modal closing, and the entry really landing '
    'in the real entries Hive box',
    (tester) async {
      adapter.queueJsonResponse(200, {
        'data': {
          'id': 'e2e-entry-1',
          'content': 'Hoje foi um bom dia.',
          'source': 'manual',
          'chatMessageId': null,
          'occurredAt': '2026-01-01T00:00:00Z',
          'serverRevision': 1,
          'createdAt': '2026-01-01T00:00:00Z',
          'updatedAt': '2026-01-01T00:00:00Z',
        },
      });

      await tester.pumpWidget(
        const MaterialApp(home: HomeChatPlaceholderScreen()),
      );

      await tester.tap(find.byIcon(Icons.add));
      await tester.pumpAndSettle();

      expect(find.byType(TextField), findsOneWidget);

      await tester.enterText(find.byType(TextField), 'Hoje foi um bom dia.');
      await tester.pump();
      await tester.tap(find.widgetWithText(ElevatedButton, 'Salvar'));
      await tester.pumpAndSettle();

      // Exactly one real request left through the fake transport, built
      // by the real UrlBuilder/HeaderInterceptor, not a mock of ApiClient.
      expect(adapter.requests, hasLength(1));
      final sent = adapter.requests.single;
      expect(sent.path, sl<UrlBuilder>().build('entries-create'));
      expect(sent.data, {'content': 'Hoje foi um bom dia.', 'source': 'manual'});
      expect(sent.headers['apikey'], dotenv.get('SUPABASE_ANON_KEY'));
      expect(
        sent.headers['Authorization'],
        'Bearer e2e-test-access-token',
      );

      // Success closed the modal.
      expect(find.byType(TextField), findsNothing);

      // The real write-through happened against the real Hive box.
      final box = sl<Box<Map>>();
      final stored = box.get('e2e-entry-1');
      expect(stored, isNotNull);
      expect(stored!['content'], 'Hoje foi um bom dia.');
      expect(stored['source'], 'manual');
    },
  );

  testWidgets(
    'failure path: a non-retryable backend error (VALIDATION_ERROR) surfaces '
    'through the real pipeline as the inline Failure.message, re-enables '
    'Salvar, keeps the modal open, fires exactly one request (no retry — '
    "VALIDATION_ERROR isn't one of the 6 retryable codes), and never writes "
    'to the real entries Hive box',
    (tester) async {
      adapter.queueJsonResponse(400, {
        'code': 'VALIDATION_ERROR',
        'message': 'Conteúdo inválido.',
        'retryable': false,
      });

      await tester.pumpWidget(
        const MaterialApp(home: HomeChatPlaceholderScreen()),
      );

      await tester.tap(find.byIcon(Icons.add));
      await tester.pumpAndSettle();

      await tester.enterText(find.byType(TextField), 'Hoje foi um bom dia.');
      await tester.pump();
      await tester.tap(find.widgetWithText(ElevatedButton, 'Salvar'));
      await tester.pumpAndSettle();

      expect(adapter.requests, hasLength(1));
      expect(find.text('Conteúdo inválido.'), findsOneWidget);

      // Modal stays open, Salvar re-enabled (text is still present).
      expect(find.byType(TextField), findsOneWidget);
      final salvarButton = tester.widget<ElevatedButton>(
        find.widgetWithText(ElevatedButton, 'Salvar'),
      );
      expect(salvarButton.onPressed, isNotNull);

      final box = sl<Box<Map>>();
      expect(box.values, isEmpty);
    },
  );
}

